					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual NZDocsMAFCoverSheetLookups GetNewLookups()
		{
			return new NZDocsMAFCoverSheetLookups(this);
		}

		NZDocsMAFCoverSheetLookups fLookups;

		#endregion

		#region Validation

		protected override void RunPreSaveValidationCore()
		{
			Validation.ValidateAll();
			base.RunPreSaveValidationCore(); // call RunPreSaveValidationCore() on all children then fire OnNotificationsChanged()
		}

		public NZDocsMAFCoverSheetValidation Validation
		{
			get { return GetNewValidation(); }
		}

		protected virtual NZDocsMAFCoverSheetValidation GetNewValidation()
		{
			return new NZDocsMAFCoverSheetValidation(this);
		}

		#endregion
	}
}
